void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // Slightly more aggressive threshold reduction

    // Adjust rephase_limit based on recent LBD performance
    if (lbd_queue_size == 50) {
        double fast_avg = fast_lbd_sum / lbd_queue_size;
        if (fast_avg > 10.0) {
            rephase_limit += 16384;  // Increase limit if LBD is high
        } else {
            rephase_limit += 4096;   // Smaller increase if LBD is low
        }
    } else {
        rephase_limit += 8192;
    }

    // Update saved phases based on activity scores
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Prefer current assignment for high-activity variables
            if (activity[i] > 1e-3 && rand() % 100 < 80) {
                saved[i] = value[i];
            }
        } else {
            // For unassigned variables, use local best if available
            if (local_best[i] != 0 && rand() % 100 < 70) {
                saved[i] = local_best[i];
            } else if (activity[i] > 1e-3 && rand() % 100 < 60) {
                // High activity variables get random phase
                saved[i] = (rand() % 2) ? 1 : -1;
            }
        }
    }
}
